_bit_to_str:                        // rdi = значение, rsi = вид (0 num, 1 dec, 2 string, 3 bool)
    cmp rsi, 0
    je _bit_num_str
    cmp rsi, 1
    je _bit_dec_str
    cmp rsi, 3
    je _bit_bool_str
    mov rax, rdi
    ret

_bit_cat:                           // rdi = a, rsi = b → новая строка a+b
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    mov rbx, rdi
    mov r12, rsi
    call strlen@PLT
    mov r13, rax
    mov rdi, r12
    call strlen@PLT
    mov r14, rax
    lea rdi, [r13 + r14 + 1]
    call _bit_alloc
    mov r15, rax
    mov rdi, r15
    mov rsi, rbx
    mov rdx, r13
    call memcpy@PLT
    lea rdi, [r15 + r13]
    mov rsi, r12
    lea rdx, [r14 + 1]
    call memcpy@PLT
    mov rax, r15
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_eq:                        // rdi, rsi = строки → 1 если равны
    push rbp
    mov rbp, rsp
    call strcmp@PLT
    test eax, eax
    sete al
    movzx eax, al
    pop rbp
    ret

_bit_str_starts:                    // rdi=строка, rsi=начало → 1/0
1:  movzx eax, byte ptr [rsi]
    test al, al
    jz 2f
    movzx ecx, byte ptr [rdi]
    cmp al, cl
    jne 3f
    inc rdi
    inc rsi
    jmp 1b
2:  mov eax, 1
    ret
3:  xor eax, eax
    ret

_bit_str_ends:                      // rdi=строка, rsi=конец → 1/0
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    mov rdi, rsi
    call strlen@PLT
    mov r13, rax
    mov rdi, rbx
    call strlen@PLT
    cmp r13, rax
    jg 3f
    lea rdi, [rbx + rax]
    sub rdi, r13
    mov rsi, r12
    mov rcx, r13
1:  test rcx, rcx
    jz 2f
    movzx edx, byte ptr [rdi]
    movzx r8d, byte ptr [rsi]
    cmp dl, r8b
    jne 3f
    inc rdi
    inc rsi
    dec rcx
    jmp 1b
2:  mov eax, 1
    jmp 4f
3:  xor eax, eax
4:  pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_trim:                      // rdi=строка → новая строка без краёв-пробелов
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov r12, rdi
1:  movzx eax, byte ptr [r12]
    cmp al, 0x20
    je 2f
    cmp al, 0x09
    je 2f
    cmp al, 0x0A
    je 2f
    cmp al, 0x0D
    je 2f
    jmp 3f
2:  inc r12
    jmp 1b
3:  mov rdi, r12
    call strlen@PLT
    mov r13, rax
4:  test r13, r13
    jz 6f
    movzx eax, byte ptr [r12 + r13 - 1]
    cmp al, 0x20
    je 5f
    cmp al, 0x09
    je 5f
    cmp al, 0x0A
    je 5f
    cmp al, 0x0D
    je 5f
    jmp 6f
5:  dec r13
    jmp 4b
6:  lea rdi, [r13 + 1]
    call _bit_alloc
    mov r14, rax
    mov rdi, rax
    mov rsi, r12
    mov rdx, r13
    call memcpy@PLT
    mov byte ptr [r14 + r13], 0
    mov rax, r14
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_substr:                        // rdi=указатель, rsi=длина → новая строка
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    lea rdi, [r12 + 1]
    call _bit_alloc
    mov r13, rax
    mov rdi, rax
    mov rsi, rbx
    mov rdx, r12
    call memcpy@PLT
    mov byte ptr [r13 + r12], 0
    mov rax, r13
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_split:                     // rdi=строка, rsi=разделитель → mas строк
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    mov rbx, rdi
    mov r12, rsi
    mov rdi, rsi
    call strlen@PLT
    mov r13, rax
    mov rdi, -1
    xor esi, esi
    call _bit_mas_new
    mov r14, rax
    test r13, r13
    jnz 10f
    mov rdi, rbx
    call strlen@PLT
    mov rsi, rax
    mov rdi, rbx
    call _bit_substr
    mov rsi, rax
    mov rdi, r14
    xor edx, edx
    call _bit_mas_add
    jmp 9f
10: mov r15, rbx
11: movzx eax, byte ptr [r15]
    test al, al
    jz 15f
    xor ecx, ecx
12: cmp rcx, r13
    jge 16f
    movzx eax, byte ptr [r15 + rcx]
    movzx edx, byte ptr [r12 + rcx]
    cmp al, dl
    jne 17f
    inc rcx
    jmp 12b
17: inc r15
    jmp 11b
16: mov rdi, rbx
    mov rsi, r15
    sub rsi, rbx
    call _bit_substr
    mov rsi, rax
    mov rdi, r14
    xor edx, edx
    call _bit_mas_add
    lea rbx, [r15 + r13]
    jmp 10b
15: mov rdi, rbx
    mov rsi, r15
    sub rsi, rbx
    call _bit_substr
    mov rsi, rax
    mov rdi, r14
    xor edx, edx
    call _bit_mas_add
9:  mov rax, r14
    add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_replace:                   // rdi=строка, rsi=что, rdx=на что → новая строка
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 8
    mov rbx, rdi
    mov r12, rsi
    mov r13, rdx
    mov rdi, r12
    call strlen@PLT
    mov r14, rax
    test r14, r14
    jnz 1f
    mov rdi, rbx
    call strlen@PLT
    mov rsi, rax
    mov rdi, rbx
    call _bit_substr
    jmp 9f
1:  mov rdi, r13
    call strlen@PLT
    mov r15, rax
    mov rdi, rbx
    call strlen@PLT
    mov [rsp], rax
    mov r8, rbx
    xor r9d, r9d
2:  movzx eax, byte ptr [r8]
    test al, al
    jz 5f
    xor ecx, ecx
3:  cmp rcx, r14
    jge 4f
    movzx eax, byte ptr [r8 + rcx]
    movzx edx, byte ptr [r12 + rcx]
    cmp al, dl
    jne 6f
    inc rcx
    jmp 3b
4:  inc r9
    add r8, r14
    jmp 2b
6:  inc r8
    jmp 2b
5:  mov rax, r15
    sub rax, r14
    imul rax, r9
    add rax, [rsp]
    lea rdi, [rax + 1]
    call _bit_alloc
    mov r10, rax
    mov r11, rax
    mov r8, rbx
7:  movzx eax, byte ptr [r8]
    test al, al
    jz 11f
    xor ecx, ecx
8:  cmp rcx, r14
    jge 10f
    movzx eax, byte ptr [r8 + rcx]
    movzx edx, byte ptr [r12 + rcx]
    cmp al, dl
    jne 12f
    inc rcx
    jmp 8b
10: xor ecx, ecx
13: cmp rcx, r15
    jge 14f
    movzx eax, byte ptr [r13 + rcx]
    mov [r11], al
    inc r11
    inc rcx
    jmp 13b
14: add r8, r14
    jmp 7b
12: movzx eax, byte ptr [r8]
    mov [r11], al
    inc r11
    inc r8
    jmp 7b
11: mov byte ptr [r11], 0
    mov rax, r10
9:  add rsp, 8
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_str_sz:                        // rdi = строка → сколько символов (UTF-8)
    xor eax, eax
1:  movzx ecx, byte ptr [rdi]
    test ecx, ecx
    jz 2f
    inc rdi
    and ecx, 0xC0
    cmp ecx, 0x80
    je 1b
    inc rax
    jmp 1b
2:  ret

// массив: [0] данные, [8] длина, [16] ёмкость, [24] лимит (-1 = нет)
_bit_mas_new:                       // rdi = лимит, rsi = сколько элементов
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    mov edi, 32
    call _bit_alloc
    mov r13, rax
    mov r14, 4
    cmp r12, r14
    cmovg r14, r12
    lea rdi, [r14*8]
    call _bit_alloc
    mov [r13], rax
    mov [r13 + 8], r12
    mov [r13 + 16], r14
    mov [r13 + 24], rbx
    mov rax, r13
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_mas_add:                       // rdi = массив, rsi = значение, rdx = строка программы
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    mov r13, rdx
    mov rax, [rbx + 24]
    mov rcx, [rbx + 8]
    test rax, rax
    js 1f
    cmp rcx, rax
    jl 1f
    lea rdi, [rip + Lrt_full]
    mov rsi, r13
    call _bit_die
1:  mov rdx, [rbx + 16]
    cmp rcx, rdx
    jl 2f
    shl rdx, 1
    mov [rbx + 16], rdx
    mov rdi, [rbx]
    lea rsi, [rdx*8]
    call realloc@PLT
    test rax, rax
    jz _bit_oom
    mov [rbx], rax
2:  mov rax, [rbx]
    mov rcx, [rbx + 8]
    mov [rax + rcx*8], r12
    inc rcx
    mov [rbx + 8], rcx
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_mas_insert:                    // rdi=массив, rsi=i, rdx=значение, rcx=строка
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    mov r13, rdx
    mov r14, rcx
    mov rax, [rbx + 24]
    mov rcx, [rbx + 8]
    test rax, rax
    js 1f
    cmp rcx, rax
    jl 1f
    lea rdi, [rip + Lrt_full]
    mov rsi, r14
    call _bit_die
1:  mov rdx, [rbx + 16]
    cmp rcx, rdx
    jl 2f
    shl rdx, 1
    mov [rbx + 16], rdx
    mov rdi, [rbx]
    lea rsi, [rdx*8]
    call realloc@PLT
    test rax, rax
    jz _bit_oom
    mov [rbx], rax
2:  mov rax, [rbx]
    mov rcx, [rbx + 8]
3:  cmp rcx, r12
    jle 4f
    mov rdx, [rax + rcx*8 - 8]
    mov [rax + rcx*8], rdx
    dec rcx
    jmp 3b
4:  mov [rax + r12*8], r13
    mov rcx, [rbx + 8]
    inc rcx
    mov [rbx + 8], rcx
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_mas_remove:                    // rdi=массив, rsi=i
    mov rax, [rdi]
    mov rcx, rsi
    mov rdx, [rdi + 8]
    dec rdx
1:  cmp rcx, rdx
    jge 2f
    mov r8, [rax + rcx*8 + 8]
    mov [rax + rcx*8], r8
    inc rcx
    jmp 1b
2:  mov rcx, [rdi + 8]
    dec rcx
    mov [rdi + 8], rcx
    ret

_bit_ipow:                          // rdi=основание, rsi=степень → rax (целая степень; отриц. → 0)
    mov rax, 1
    test rsi, rsi
    js 2f
    mov rcx, rsi
1:  test rcx, rcx
    jz 3f
    imul rax, rdi
    dec rcx
    jmp 1b
2:  xor eax, eax
3:  ret

_bit_mas_str:                       // rdi = массив, rsi = вид элементов → "(1, 2, 3)"
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    mov rbx, rdi
    mov r12, rsi
    xor r13d, r13d
    lea r14, [rip + Lrt_lpar]
1:  cmp r13, [rbx + 8]
    jge 3f
    test r13, r13
    jz 2f
    mov rdi, r14
    lea rsi, [rip + Lrt_comma]
    call _bit_cat
    mov r14, rax
2:  mov rax, [rbx]
    mov rdi, [rax + r13*8]
    mov rsi, r12
    call _bit_to_str
