    mov rdi, r14
    call _bit_cat
    mov r14, rax
    inc r13
    jmp 1b
3:  mov rdi, r14
    lea rsi, [rip + Lrt_rpar]
    call _bit_cat
    pop r14
    pop r13
    pop r12
    pop rbx
    pop rbp
    ret

_bit_readline:                      // rdi = строка программы → введённый текст
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 16
    mov rbx, rdi
    xor edi, edi
    call fflush@PLT
    mov qword ptr [rsp], 0
    mov qword ptr [rsp + 8], 0
    mov rdi, rsp
    lea rsi, [rsp + 8]
    mov rax, [rip + stdin@GOTPCREL]
    mov rdx, [rax]
    call getline@PLT
    test rax, rax
    js 9f
    mov r12, [rsp]
    lea rcx, [r12 + rax]
1:  cmp rcx, r12
    je 2f
    movzx edx, byte ptr [rcx - 1]
    cmp edx, 10
    je 3f
    cmp edx, 13
    jne 2f
3:  dec rcx
    mov byte ptr [rcx], 0
    jmp 1b
2:  mov rax, r12
    add rsp, 16
    pop r12
    pop rbx
    pop rbp
    ret
9:  lea rdi, [rip + Lrt_eof]
    mov rsi, rbx
    call _bit_die

_bit_input_num:                     // rdi = есть границы, rsi = от, rdx = до, rcx = строка
    push rbp
